SELECT location, dept_name, CASE WHEN budget >= 3743000 THEN 'high' WHEN budget >= 1093000 THEN 'mid' ELSE 'low' END AS budget_bucket, SORT_ARRAY(COLLECT_SET(location)) AS location_list, MAX(budget) AS max_budget, COUNT(DISTINCT budget) AS unique_locations FROM departments WHERE location IN ('Singapore', 'Berlin') AND location IN ('Bangkok', 'New York') AND location IN ('Tokyo', 'Bangkok', 'London') GROUP BY 1, 2, 3 HAVING unique_locations > 5;
